 static int[][] calls={new int[5],new int[5]};
 static class CustomDecoder extends DecoderFallback{String value;int maximum,mode,calls;CustomDecoder(String v,int n,int m){value=v;maximum=n;mode=m;}public int get_MaxCharCount(){return maximum;}public DecoderFallbackBuffer CreateFallbackBuffer(){calls++;if(mode==9)return null;if(mode==10)throw new InvalidOperationException("buffer failure");return new DB(value,mode);}}
 static class Cursor{String value;int mode,pos,d;Cursor(String v,int m,int d){value=v;mode=m;this.d=d;}boolean fallback(){calls[d][1]++;if(mode==5)throw new InvalidOperationException("buffer failure");pos=0;return mode!=4;}char next(){calls[d][0]++;if(mode==3)throw new InvalidOperationException("buffer failure");return pos<value.length()?value.charAt(pos++):0;}int remaining(){calls[d][2]++;if(mode==2)throw new InvalidOperationException("buffer failure");return mode==1?0:Math.max(value.length()-pos,0);}boolean previous(){calls[d][3]++;if(mode==7)throw new InvalidOperationException("buffer failure");if(mode==6){pos--;return true;}return false;}void reset(){calls[d][4]++;if(mode==8)throw new InvalidOperationException("buffer failure");while(next()!=0){}}}
 static class DB extends DecoderFallbackBuffer{Cursor c;DB(String v,int m){c=new Cursor(v,m,1);}public boolean Fallback(Byte[] b,int i){return c.fallback();}public char GetNextChar(){return c.next();}public int get_Remaining(){return c.remaining();}public boolean MovePrevious(){return c.previous();}public void Reset(){c.reset();}}
